arguments.command:
cd /app; python3 - <<'EOF'
import re,glob,collections
def norm(s):
    s=re.sub(r'\d+','N',s)
    s=re.sub(r'\b(Contoso|Northwind|Globex|Initech|Umbrella)\b','P',s)
    s=re.sub(r'\b[A-Z]\. [A-Z][a-z]+\b','X',s)
    s=re.sub(r'\b(catalog|ledger|orders|payouts|refunds|settlement|disputes|reconciliation|onboarding|webhooks)\b','Q',s)
    s=re.sub(r'\b(sre-core|data-plane|edge-platform|identity|billing|fraud-ops|payments-api|partner-integrations)\b','T',s)
    s=re.sub(r'gw-edge-N','H',s)
    return s
sents={}
cnt=collections.Counter()
for f in sorted(glob.glob('dossier/*.md')):
    for para in open(f).read().split('\n'):
        for s in re.split(r'(?<=[.])\s+',para):
            if not s or s.startswith('#'): continue
            n=norm(s); cnt[n]+=1; sents.setdefault(n,[]).append((f,s))
for n,c in cnt.items():
    if c<=2:
        for f,s in sents[n]:
            if '/1' in f: print(f[8:10],s)
EOF

